import {test} from 'node:test';import assert from 'node:assert/strict';import {preview,canExport} from './feature.mjs';
test('preview stays bounded without mutating its input',()=>{const items=Array.from({length:80},(_,id)=>({id}));const copy=structuredClone(items);const result=preview(items);assert.ok(result.length>0&&result.length<=20);assert.deepEqual(items,copy);assert.deepEqual(result,items.slice(0,result.length));});
test('documented export policy denies other roles',()=>{assert.equal(canExport('admin'),true);assert.equal(canExport('viewer'),false);assert.equal(canExport('unknown'),false);});

test('preview shows the first ten items by default', () => {
  const items = Array.from({ length: 80 }, (_, id) => ({ id }));
  assert.deepEqual(preview(items), items.slice(0, 10));
});

test('preview preserves a list shorter than its limit', () => {
  const items = [{ id: 1 }, { id: 2 }];
  assert.deepEqual(preview(items), items);
});

test('preview returns an independent empty list', () => {
  const items = [];
  const result = preview(items);
  assert.deepEqual(result, []);
  assert.notStrictEqual(result, items);
  result.push({ id: 1 });
  assert.deepEqual(items, []);
});

test('export denies every role except the exact admin role', () => {
  for (const role of [undefined, null, '', 'Admin', 'editor', {}, ['admin']]) {
    assert.equal(canExport(role), false);
  }
});
